import { ZodFirstPartyTypeKind, ZodTypeDef } from 'zod';
import { JsonSchema7AnyType, parseAnyDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/any';
import { JsonSchema7ArrayType, parseArrayDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/array';
import { JsonSchema7BigintType, parseBigintDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/bigint';
import { JsonSchema7BooleanType, parseBooleanDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/boolean';
import { parseBrandedDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/branded';
import { parseCatchDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/catch';
import { JsonSchema7DateType, parseDateDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/date';
import { parseDefaultDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/default';
import { parseEffectsDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/effects';
import { JsonSchema7EnumType, parseEnumDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/enum';
import { JsonSchema7AllOfType, parseIntersectionDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/intersection';
import { JsonSchema7LiteralType, parseLiteralDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/literal';
import { JsonSchema7MapType, parseMapDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/map';
import { JsonSchema7NativeEnumType, parseNativeEnumDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/nativeEnum';
import { JsonSchema7NeverType, parseNeverDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/never';
import { JsonSchema7NullType, parseNullDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/null';
import { JsonSchema7NullableType, parseNullableDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/nullable';
import { JsonSchema7NumberType, parseNumberDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/number';
import { JsonSchema7ObjectType, parseObjectDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/object';
import { parseOptionalDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/optional';
import { parsePipelineDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/pipeline';
import { parsePromiseDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/promise';
import { JsonSchema7RecordType, parseRecordDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/record';
import { JsonSchema7SetType, parseSetDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/set';
import { JsonSchema7StringType, parseStringDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/string';
import { JsonSchema7TupleType, parseTupleDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/tuple';
import { JsonSchema7UndefinedType, parseUndefinedDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/undefined';
import { JsonSchema7UnionType, parseUnionDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/union';
import { JsonSchema7UnknownType, parseUnknownDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/unknown';
import { Refs, Seen } from 'openai/src/_vendor/zod-to-json-schema/Refs';
import { parseReadonlyDef } from 'openai/src/_vendor/zod-to-json-schema/parsers/readonly';
import { ignoreOverride } from 'openai/src/_vendor/zod-to-json-schema/Options';

type JsonSchema7RefType = { $ref: string };
type JsonSchema7Meta = {
  title?: string;
  default?: any;
  description?: string;
  markdownDescription?: string;
};

export type JsonSchema7TypeUnion =
  | JsonSchema7StringType
  | JsonSchema7ArrayType
  | JsonSchema7NumberType
  | JsonSchema7BigintType
  | JsonSchema7BooleanType
  | JsonSchema7DateType
  | JsonSchema7EnumType
  | JsonSchema7LiteralType
  | JsonSchema7NativeEnumType
  | JsonSchema7NullType
  | JsonSchema7NumberType
  | JsonSchema7ObjectType
  | JsonSchema7RecordType
  | JsonSchema7TupleType
  | JsonSchema7UnionType
  | JsonSchema7UndefinedType
  | JsonSchema7RefType
  | JsonSchema7NeverType
  | JsonSchema7MapType
  | JsonSchema7AnyType
  | JsonSchema7NullableType
  | JsonSchema7AllOfType
  | JsonSchema7UnknownType
  | JsonSchema7SetType;

export type JsonSchema7Type = JsonSchema7TypeUnion & JsonSchema7Meta;

export function parseDef(
  def: ZodTypeDef,
  refs: Refs,
  forceResolution = false, // Forces a new schema to be instantiated even though its def has been seen. Used for improving refs in definitions. See https://github.com/StefanTerdell/zod-to-json-schema/pull/61.
): JsonSchema7Type | undefined {
  const seenItem = refs.seen.get(def);

  if (refs.override) {
    const overrideResult = refs.override?.(def, refs, seenItem, forceResolution);

    if (overrideResult !== ignoreOverride) {
      return overrideResult;
    }
  }

  if (seenItem && !forceResolution) {
    const seenSchema = get$ref(seenItem, refs);

    if (seenSchema !== undefined) {
      if ('$ref' in seenSchema) {
        refs.seenRefs.add(seenSchema.$ref);
      }

      return seenSchema;
    }
  }

  const newItem: Seen = { def, path: refs.currentPath, jsonSchema: undefined };

  refs.seen.set(def, newItem);

  const jsonSchema = selectParser(def, (def as any).typeName, refs, forceResolution);

  if (jsonSchema) {
    addMeta(def, refs, jsonSchema);
  }

  newItem.jsonSchema = jsonSchema;

  return jsonSchema;
}

const get$ref = (
  item: Seen,
  refs: Refs,
):
  | {
      $ref: string;
    }
  | {}
  | undefined => {
  switch (refs.$refStrategy) {
    case 'root':
      return { $ref: item.path.join('/') };
    // this case is needed as OpenAI strict mode doesn't support top-level `$ref`s, i.e.
    // the top-level schema *must* be `{"type": "object", "properties": {...}}` but if we ever
    // need to define a `$ref`, relative `$ref`s aren't supported, so we need to extract
    // the schema to `#/definitions/` and reference that.
    //
    // e.g. if we need to reference a schema at
    // `["#","definitions","contactPerson","properties","person1","properties","name"]`
    // then we'll extract it out to `contactPerson_properties_person1_properties_name`
    case 'extract-to-root':
      const name = item.path.slice(refs.basePath.length + 1).join('_');

      // we don't need to extract the root schema in this case, as it's already
      // been added to the definitions
      if (name !== refs.name && refs.nameStrategy === 'duplicate-ref') {
        refs.definitions[name] = item.def;
      }

      return { $ref: [...refs.basePath, refs.definitionPath, name].join('/') };
    case 'relative':
      return { $ref: getRelativePath(refs.currentPath, item.path) };
    case 'none':
    case 'seen': {
      if (
        item.path.length < refs.currentPath.length &&
        item.path.every((value, index) => refs.currentPath[index] === value)
      ) {
        console.warn(`Recursive reference detected at ${refs.currentPath.join('/')}! Defaulting to any`);

        return {};
      }

      return refs.$refStrategy === 'seen' ? {} : undefined;
    }
  }
};

const getRelativePath = (pathA: string[], pathB: string[]) => {
  let i = 0;
  for (; i < pathA.length && i < pathB.length; i++) {
    if (pathA[i] !== pathB[i]) break;
  }
  return [(pathA.length - i).toString(), ...pathB.slice(i)].join('/');
};

const selectParser = (
  def: any,
  typeName: ZodFirstPartyTypeKind,
  refs: Refs,
  forceResolution: boolean,
): JsonSchema7Type | undefined => {
  switch (typeName) {
    case ZodFirstPartyTypeKind.ZodString:
      return parseStringDef(def, refs);
    case ZodFirstPartyTypeKind.ZodNumber:
      return parseNumberDef(def, refs);
    case ZodFirstPartyTypeKind.ZodObject:
      return parseObjectDef(def, refs);
    case ZodFirstPartyTypeKind.ZodBigInt:
      return parseBigintDef(def, refs);
    case ZodFirstPartyTypeKind.ZodBoolean:
      return parseBooleanDef();
    case ZodFirstPartyTypeKind.ZodDate:
      return parseDateDef(def, refs);
    case ZodFirstPartyTypeKind.ZodUndefined:
      return parseUndefinedDef();
    case ZodFirstPartyTypeKind.ZodNull:
      return parseNullDef(refs);
    case ZodFirstPartyTypeKind.ZodArray:
      return parseArrayDef(def, refs);
    case ZodFirstPartyTypeKind.ZodUnion:
    case ZodFirstPartyTypeKind.ZodDiscriminatedUnion:
      return parseUnionDef(def, refs);
    case ZodFirstPartyTypeKind.ZodIntersection:
      return parseIntersectionDef(def, refs);
    case ZodFirstPartyTypeKind.ZodTuple:
      return parseTupleDef(def, refs);
    case ZodFirstPartyTypeKind.ZodRecord:
      return parseRecordDef(def, refs);
    case ZodFirstPartyTypeKind.ZodLiteral:
      return parseLiteralDef(def, refs);
    case ZodFirstPartyTypeKind.ZodEnum:
      return parseEnumDef(def);
    case ZodFirstPartyTypeKind.ZodNativeEnum:
      return parseNativeEnumDef(def);
    case ZodFirstPartyTypeKind.ZodNullable:
      return parseNullableDef(def, refs);
    case ZodFirstPartyTypeKind.ZodOptional:
      return parseOptionalDef(def, refs);
    case ZodFirstPartyTypeKind.ZodMap:
      return parseMapDef(def, refs);
    case ZodFirstPartyTypeKind.ZodSet:
      return parseSetDef(def, refs);
    case ZodFirstPartyTypeKind.ZodLazy:
      return parseDef(def.getter()._def, refs);
    case ZodFirstPartyTypeKind.ZodPromise:
      return parsePromiseDef(def, refs);
    case ZodFirstPartyTypeKind.ZodNaN:
    case ZodFirstPartyTypeKind.ZodNever:
      return parseNeverDef();
    case ZodFirstPartyTypeKind.ZodEffects:
      return parseEffectsDef(def, refs, forceResolution);
    case ZodFirstPartyTypeKind.ZodAny:
      return parseAnyDef();
    case ZodFirstPartyTypeKind.ZodUnknown:
      return parseUnknownDef();
    case ZodFirstPartyTypeKind.ZodDefault:
      return parseDefaultDef(def, refs);
    case ZodFirstPartyTypeKind.ZodBranded:
      return parseBrandedDef(def, refs);
    case ZodFirstPartyTypeKind.ZodReadonly:
      return parseReadonlyDef(def, refs);
    case ZodFirstPartyTypeKind.ZodCatch:
      return parseCatchDef(def, refs);
    case ZodFirstPartyTypeKind.ZodPipeline:
      return parsePipelineDef(def, refs);
    case ZodFirstPartyTypeKind.ZodFunction:
    case ZodFirstPartyTypeKind.ZodVoid:
    case ZodFirstPartyTypeKind.ZodSymbol:
      return undefined;
    default:
      return ((_: never) => undefined)(typeName);
  }
};

const addMeta = (def: ZodTypeDef, refs: Refs, jsonSchema: JsonSchema7Type): JsonSchema7Type => {
  if (def.description) {
    jsonSchema.description = def.description;

    if (refs.markdownDescription) {
      jsonSchema.markdownDescription = def.description;
    }
  }
  return jsonSchema;
};
